package com.hardcraft.mobs;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class BossRulesTest{@Test void phasesAndScalingRemainKillable(){var b=new BossDefinition("titan",200,50,List.of(.66,.33),10);assertEquals(2,b.phase(120,200));assertEquals(3,b.phase(60,200));assertEquals(300,b.maximumHealth(3));assertEquals(100,b.rescale(150,300,1));}@Test void participationUsesDeclaredDamage(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();assertEquals(Set.of(a),BossRules.eligible(Map.of(a,10d,b,9d),10));}@Test void targetLoadIsCheap(){var b=new BossDefinition("titan",200,50,List.of(.66,.33),10);long start=System.nanoTime();for(int i=0;i<1_000_000;i++){b.maximumHealth(20);b.phase(100,1150);}assertTrue(System.nanoTime()-start<2_000_000_000L);}@Test void crashWindowsAreFailClosed(@TempDir Path dir){UUID e=UUID.randomUUID(),p=UUID.randomUUID();Path db=dir.resolve("mobs.db");var r=new LootRepository(db);r.migrate();assertTrue(r.create(e,p,"titan"));assertFalse(r.create(e,p,"titan"));assertEquals(1,new LootRepository(db).pending(p).size());assertTrue(r.begin(e,p));assertEquals(1,new LootRepository(db).recoverUncertain());assertEquals(LootRepository.State.UNCERTAIN,r.state(e,p));assertFalse(r.begin(e,p));}@Test void confirmedDeliveryNeverRepeats(@TempDir Path dir){UUID e=UUID.randomUUID(),p=UUID.randomUUID();var r=new LootRepository(dir.resolve("mobs.db"));r.migrate();r.create(e,p,"titan");assertTrue(r.begin(e,p));r.delivered(e,p);assertEquals(LootRepository.State.DELIVERED,r.state(e,p));assertFalse(r.begin(e,p));}}